const container = document.querySelector('#root');
const root = createRoot(container);
root.render(<App />);

import path from 'node:path';
import { fileURLToPath } from 'node:url';

import fs from 'fs-extra';

import { mergeTokensData } from './mergeTokensData.ts';

export type StrNum = string | number;

export type RegularCompactObj<Type = StrNum> = {
	regular?: Type;
	compact?: Type;
};

type TokenValueObject = Record<string, StrNum | RegularCompactObj>;

type TokenValue = StrNum | TokenValueObject;

export type Token = {
	tags: Array<string>;
	desc: string;
	value: TokenValue;
};

export type Tokens = Record<string, Token>;
type TokensData = Record<string, Tokens>;

function prepareTokensData() {
	const __filename = fileURLToPath(import.meta.url);
	const __dirname = path.dirname(__filename);
	const ROOT_DIR = path.resolve(__dirname, '../..');
	const THEMES_DIR = path.resolve(ROOT_DIR, './dist/themes');
	const RESULT_DATA_FILE = path.resolve(ROOT_DIR, './docs/public/static/data/tokensData.json');

	if (fs.existsSync(RESULT_DATA_FILE)) {
		fs.removeSync(RESULT_DATA_FILE);
	}

	const tokensData: TokensData = {};
	fs.readdirSync(THEMES_DIR).forEach((dir) => {
		const docsRaw = fs.readFileSync(path.resolve(THEMES_DIR, `./${dir}/docs.json`), 'utf-8');
		const tokensRaw = fs.readFileSync(path.resolve(THEMES_DIR, `./${dir}/index.json`), 'utf-8');
		const docs = JSON.parse(docsRaw);
		const tokens = JSON.parse(tokensRaw);

		tokensData[dir] = mergeTokensData(docs, tokens);
	});

	fs.createFileSync(RESULT_DATA_FILE);
	fs.writeFileSync(RESULT_DATA_FILE, JSON.stringify(tokensData, null, '  '), 'utf-8');
}

prepareTokensData();

import type { RegularCompactObj, StrNum, Token, Tokens } from './prepareTokensData.ts';

const isObject = (value: unknown): value is Record<string, unknown> =>
	Object.prototype.toString.call(value) === '[object Object]' &&
	!Array.isArray(value) &&
	value !== null;

const transformRegularCompactObj = (
	value: RegularCompactObj<Record<string, StrNum>>,
): Record<string, RegularCompactObj | StrNum> => {
	const result: Record<string, RegularCompactObj | StrNum> = {};
	const regularKeys = value.regular ? Object.keys(value.regular) : [];
	const compactKeys = value.compact ? Object.keys(value.compact) : [];
	const uniqKeys = regularKeys
		.concat(compactKeys)
		.filter((key, index, arr) => arr.indexOf(key) === index);
	uniqKeys.forEach((key) => {
		const regular = value?.regular?.[key];
		const compact = value?.compact?.[key];
		if (regular === compact) {
			result[key] = regular;
			return;
		}
		result[key] = {};
		if (regular) {
			(result[key] as RegularCompactObj).regular = regular;
		}
		if (compact) {
			(result[key] as RegularCompactObj).compact = compact;
		}
	});
	return result;
};

export function mergeTokensData(
	docs: Record<string, Pick<Token, 'tags' | 'desc'>>,
	tokens: Record<
		string,
		StrNum | RegularCompactObj<Record<string, StrNum>> | Record<string, StrNum>
	>,
): Tokens {
	const result: Record<string, Token> = {};
	Object.keys(docs).forEach((docsKey) => {
		const value = tokens[docsKey];

		if (!value) {
			return;
		}

		result[docsKey] = {
			...docs[docsKey],
			value,
		};

		if (isObject(value) && (isObject(value.regular) || isObject(value.compact))) {
			result[docsKey].value = transformRegularCompactObj(value);
		}
	});
	return result;
}

